For example, the square distance between $\mathbf{x}_i$ and $\mathbf{x}_j$ is~\cite{jain2012metric,weinberger2005distance}:
\begin{equation}
d_{\mathbf{W}} = (\mathbf{\mathbf{x}_i-\mathbf{x}_j})^\top \mathbf{W} (\mathbf{\mathbf{x}_i-\mathbf{x}_j}),
\label{eq:linear_DML}
\end{equation}
where the factorisation of the matrix $\mathbf{W} = \mathbf{G}\mathbf{G}^\top$ (with $\mathbf{G} \in \mathbb R^{n \times m}$) allows us to formulate the following optimisation problem: $\mathbf{G}^* = \arg \max_{\mathbf{G}} \text{tr} \left  ( (\mathbf{G}^\top \mathbf{S}_w \mathbf{G})^{-1} (\mathbf{G}^\top \mathbf{S}_b \mathbf{G}) \right ) $, with $ \mathbf{S}_k = \sum_{ij} \mathbf{Y}_k (\mathbf{\mathbf{x}_i-\mathbf{x}_j})(\mathbf{\mathbf{x}_i-\mathbf{x}_j})^\top$, 
$\mathbf{Y}_w = \mathbf{Y}$, $\mathbf{Y}_b = 1 - \mathbf{Y}$, and $\mathbf{Y}_{ij}=1$ if $y_i=y_j$ and $\mathbf{Y}_{ij}=0$, otherwise.

\begin{equation}
d_{\mathbf{W}} = (\mathbf{\mathbf{x}_i-\mathbf{x}_j})^\top \mathbf{W} (\mathbf{\mathbf{x}_i-\mathbf{x}_j}),
\label{eq:linear_DML}
\end{equation}

We consider the following definition of a deep ConvNet:
\begin{equation}
f(\mathbf{x},\theta_f) = f_{\text{out}} \circ r_{L} \circ h_L \circ f_L \circ ... \circ r_1 \circ h_1 \circ f_1(\mathbf{x}),
\label{eq:def_CNN}
\end{equation}
where the parameter $\theta_f$ is formed by the network weight matrices, bias vectors, and normalisation parameters for each layer $l \in \{1,...,L\}$, $f_l(.)$ represents the pre-activation function (\ie, the linear transforms in the convolutional layers), $h_l(.)$ represents a normalisation function, and $r_l(.)$ is a non-linear activation function (e.g., ReLU~\cite{nair2010rectified}).

\begin{equation}
f(\mathbf{x},\theta_f) = f_{\text{out}} \circ r_{L} \circ h_L \circ f_L \circ ... \circ r_1 \circ h_1 \circ f_1(\mathbf{x}),
\label{eq:def_CNN}
\end{equation}

A siamese network is then represented by two identical deep ConvNets trained using pairs of labelled inputs, where one possible loss function (called pairwise loss) minimises the distance between embedded features of the same class and maximises the distance between embedded features of different classes, as follows~\cite{chopra2005learning,masci2014descriptor}:
\begin{equation}
\begin{split}
J_1^s( \mathbf{x}_i,\mathbf{x}_j, & \theta_f ) = \delta(y_i-y_j)\| f^{(1)}(\mathbf{x}_i, \theta_f) - f^{(2)}(\mathbf{x}_j, \theta_f) \|_2   - \\
& (1 - \delta(y_i-y_j))\| f^{(1)}(\mathbf{x}_i, \theta_f) - f^{(2)}(\mathbf{x}_j, \theta_f) \|_2, 
\end{split}
\label{eq:loss_siamese_embedding}
\end{equation}
where $\delta(.)$ is the Dirac delta function and $f^{(1)}(\mathbf{x},\theta_f)$ is constrained to equal to $f^{(2)}(\mathbf{x},\theta_f)$.

\begin{equation}
\begin{split}
J_1^s( \mathbf{x}_i,\mathbf{x}_j, & \theta_f ) = \delta(y_i-y_j)\| f^{(1)}(\mathbf{x}_i, \theta_f) - f^{(2)}(\mathbf{x}_j, \theta_f) \|_2   - \\
& (1 - \delta(y_i-y_j))\| f^{(1)}(\mathbf{x}_i, \theta_f) - f^{(2)}(\mathbf{x}_j, \theta_f) \|_2, 
\end{split}
\label{eq:loss_siamese_embedding}
\end{equation}

Alternatively, the siamese network can be trained as a pairwise similarity estimator, with a pairwise similarity loss that can be defined as:
\begin{equation}
\begin{split}
J_2^s( \mathbf{x}_i,\mathbf{x}_j, \theta_g ) = & \delta(y_i-y_j)   (1/(\kappa+g(\mathbf{x}_i, \mathbf{x}_j, \theta_g ) ))   \\
&+(1 - \delta(y_i-y_j))g(\mathbf{x}_i, \mathbf{x}_j, \theta_g ) , 
\end{split}
\label{eq:loss_siamese_classifier}
\end{equation}
where the ConvNet $g(\mathbf{x}_i, \mathbf{x}_j, \theta_g)$ returns the similarity between the descriptors $\mathbf{x}_i$ and $\mathbf{x}_j$, with $\kappa$ representing a small positive constant.

\begin{equation}
\begin{split}
J_2^s( \mathbf{x}_i,\mathbf{x}_j, \theta_g ) = & \delta(y_i-y_j)   (1/(\kappa+g(\mathbf{x}_i, \mathbf{x}_j, \theta_g ) ))   \\
&+(1 - \delta(y_i-y_j))g(\mathbf{x}_i, \mathbf{x}_j, \theta_g ) , 
\end{split}
\label{eq:loss_siamese_classifier}
\end{equation}

The triplet network~\cite{Wangcvpr14,hoffer2014deep,SchroffKPcvpr15,wohlhartcvpr15} (Fig.~\ref{fig:intro}-(d)) is an extension of the siamese network that is trained with triplets at the input (which produces an embedding) using the triplet loss function, as follows:
\begin{equation}
\begin{split}
J_1^t  &  ( \mathbf{x},\mathbf{x}^+, \mathbf{x}^-, \theta_f ) =  \\ 
& \max \left ( 0,1-\frac{ \| f^{(1)}(\mathbf{x}, \theta_f) - f^{(3)}(\mathbf{x}^-, \theta_f) \|_2 } { \| f^{(1)}(\mathbf{x}, \theta_f) - f^{(2)}(\mathbf{x}^+, \theta_f) \|_2 + m }  \right ), \\
\end{split}
\label{eq:loss_triplet_embedding}
\end{equation}
where $m$ is the margin, $\mathbf{x}^+$ and $\mathbf{x}$ belong to the same class, $\mathbf{x}^-$ and $\mathbf{x}$ are from different classes, and $f^{(1)}(.)$, $f^{(2)}(.)$ and $f^{(3)}(.)$ are constrained to be the same network.

\begin{equation}
\begin{split}
J_1^t  &  ( \mathbf{x},\mathbf{x}^+, \mathbf{x}^-, \theta_f ) =  \\ 
& \max \left ( 0,1-\frac{ \| f^{(1)}(\mathbf{x}, \theta_f) - f^{(3)}(\mathbf{x}^-, \theta_f) \|_2 } { \| f^{(1)}(\mathbf{x}, \theta_f) - f^{(2)}(\mathbf{x}^+, \theta_f) \|_2 + m }  \right ), \\
\end{split}
\label{eq:loss_triplet_embedding}
\end{equation}

Fig.~\ref{fig:global_loss}-(a) depicts the reasoning behind the design of the proposed global loss function, which is defined for the feature embedding case by:
\begin{equation}
\begin{split}
 J_1^g( \{ \mathbf{x}_i \}_{i=1}^N ,& \{ \mathbf{x}_i^+ \}_{i=1}^N, \{ \mathbf{x}_i^-\}_{i=1}^N , \theta_f ) = \\ &(\sigma^{2+}+\sigma^{2-})+\lambda \max\big(0,\mu^+ - \mu^- + t\big),
\end{split}
\label{eq:loss_global}
\end{equation}
where $\mu^+ = \sum_{i=1}^N d_i^+/N,~~ \mu^- = \sum_{i=1}^N d_i^-/N $, ~~
$\sigma^{2+} = \sum_{i=1}^N(d_i^+ -\mu^+)^2/N,~~~   \sigma^{2-} = \sum_{i=1}^N(d_i^- - \mu^-)^2/N$, with $\mu^+$ and $\sigma^{2+}$ denoting the mean and variance of the matching pair distance distribution,  
$\mu^-$ and $\sigma^{2-}$ representing the mean and variance of the non-matching pair distance distribution, 
 $d_i^+ = \frac{\lVert f^{(1)}(\mathbf{x}_i,\theta_f) - f^{(2)}(\mathbf{x}_i^+,\theta_f) \rVert_2^2}{4}$, $d_i^- = \frac{\lVert f^{(1)}(\mathbf{x}_i,\theta_f) - f^{(3)}(\mathbf{x}_i^-,\theta_f) \rVert_2^2}{4}$, 
$\lambda$ is a term that balances the importance of each term, $t$ is the margin between the mean of the matching and non-matching distance distributions and
$N$ is the size of the training set.

\begin{equation}
\begin{split}
 J_1^g( \{ \mathbf{x}_i \}_{i=1}^N ,& \{ \mathbf{x}_i^+ \}_{i=1}^N, \{ \mathbf{x}_i^-\}_{i=1}^N , \theta_f ) = \\ &(\sigma^{2+}+\sigma^{2-})+\lambda \max\big(0,\mu^+ - \mu^- + t\big),
\end{split}
\label{eq:loss_global}
\end{equation}

Given that we use SGD for the optimisation process, we need to derive the gradient of the global loss function, as follows:
\begin{equation*}
\footnotesize{
\begin{split}
\frac {\partial  J_1^g}{\partial  f(\mathbf{x}_i)} &= -\frac{1}{2N}\Big[2(d_i^+ - \mu^+)\big(f(\mathbf{x}_i^+) - f(\mathbf{x}_i)\big)+ 2(d_i^- - \mu^-)\\
&\big(f(\mathbf{x}_i^-) - f(\mathbf{x}_i)\big) + \lambda (f(\mathbf{x}_i^+) - f(\mathbf{x}_i^-)) \mathds{1}((\mu^- - \mu^+) < t) \Big],\\
\end{split}}
\end{equation*}
\begin{equation}






\footnotesize{
\begin{split}
  \frac {\partial  J_1^g}{\partial  f(\mathbf{x}_i^+)} = -\frac{1}{2N}\Big[2(d_i^+ - &\mu^+)(f(\mathbf{x}_i) - f(\mathbf{x}_i^+)) \\
&+ \lambda (f(\mathbf{x}_i ) - f(\mathbf{x}_i^+))\mathds{1}((\mu^- - \mu^+) < t) \Big],\\ 
 \frac {\partial  J_1^g}{\partial  f(\mathbf{x}_i^-)} = -\frac{1}{2N}\Big[2(d_i^- - &\mu^-)(f(\mathbf{x}_i) - f(\mathbf{x}_i^-)) \\
&+ \lambda (f(\mathbf{x}_i^-) - f(\mathbf{x}_i))\mathds{1}((\mu^- - \mu^+) < t) \Big]\\
 \label{eq:loss_global_gradient}
 \end{split}}
\end{equation}
where 
the dependence on $\theta_f$ and the channel index $f^{(.)}$ are dropped to simplify the notation, and $\mathds{1}(a)$ is an indicator function with value $1$ when $a$ is true.

\begin{equation*}
\footnotesize{
\begin{split}
\frac {\partial  J_1^g}{\partial  f(\mathbf{x}_i)} &= -\frac{1}{2N}\Big[2(d_i^+ - \mu^+)\big(f(\mathbf{x}_i^+) - f(\mathbf{x}_i)\big)+ 2(d_i^- - \mu^-)\\
&\big(f(\mathbf{x}_i^-) - f(\mathbf{x}_i)\big) + \lambda (f(\mathbf{x}_i^+) - f(\mathbf{x}_i^-)) \mathds{1}((\mu^- - \mu^+) < t) \Big],\\
\end{split}}
\end{equation*}

\begin{equation}






\footnotesize{
\begin{split}
  \frac {\partial  J_1^g}{\partial  f(\mathbf{x}_i^+)} = -\frac{1}{2N}\Big[2(d_i^+ - &\mu^+)(f(\mathbf{x}_i) - f(\mathbf{x}_i^+)) \\
&+ \lambda (f(\mathbf{x}_i ) - f(\mathbf{x}_i^+))\mathds{1}((\mu^- - \mu^+) < t) \Big],\\ 
 \frac {\partial  J_1^g}{\partial  f(\mathbf{x}_i^-)} = -\frac{1}{2N}\Big[2(d_i^- - &\mu^-)(f(\mathbf{x}_i) - f(\mathbf{x}_i^-)) \\
&+ \lambda (f(\mathbf{x}_i^-) - f(\mathbf{x}_i))\mathds{1}((\mu^- - \mu^+) < t) \Big]\\
 \label{eq:loss_global_gradient}
 \end{split}}
\end{equation}

Fig.~\ref{fig:global_loss}-(b) shows the idea behind the design of the proposed pairwise similarity global loss function, which is defined by:
\begin{equation}
\begin{split}
J_2^g = ( \{ \mathbf{x}_i \}_{i=1}^N ,& \{ \mathbf{x}_i^+ \}_{i=1}^N, \{ \mathbf{x}_i^-\}_{i=1}^N , \theta_f ) = \\ &(\sigma^{2+}+\sigma^{2-})+\lambda \max\big(0, m - (\mu^+ - \mu^-) \big),\\
\end{split}
\label{eq:loss_global_siamese}
\end{equation}
where $g(\mathbf{x},\tilde{\mathbf{x}},\theta_g)$ produces a similarity score between $\mathbf{x}$ and $\tilde{\mathbf{x}}$, $\mu^+ = \sum_{i=1}^N g(\mathbf{x}_i,\mathbf{x}_i^+,\theta_g)/N,~~ \mu^- = \sum_{i=1}^N g(\mathbf{x}_i,\mathbf{x}_i^-,\theta_g)/N $, ~~
$\sigma^{2+} = \sum_{i=1}^N(g(\mathbf{x}_i,\mathbf{x}_i^+) -\mu^+)^2/N,~~~   \sigma^{2-} = \sum_{i=1}^N(g(\mathbf{x}_i,\mathbf{x}_i^-) - \mu^-)^2/N$, with $\mu^+$ and $\sigma^{2+}$ denoting the mean and variance of the matching pair similarity distribution,  
$\mu^-$ and $\sigma^{2-}$ representing the mean and variance of the non-matching pair similarity distribution, 
$\lambda$ is a term that balances the importance of each term, $m$ is the margin between the mean of the matching and non-matching similarity distributions and
$N$ is again the size of the training set (note that we are abusing the notation with the re-definition of $\mu^+$, $\mu^-$, $\sigma^{2+}$, and $\sigma^{2-}$).

\begin{equation}
\begin{split}
J_2^g = ( \{ \mathbf{x}_i \}_{i=1}^N ,& \{ \mathbf{x}_i^+ \}_{i=1}^N, \{ \mathbf{x}_i^-\}_{i=1}^N , \theta_f ) = \\ &(\sigma^{2+}+\sigma^{2-})+\lambda \max\big(0, m - (\mu^+ - \mu^-) \big),\\
\end{split}
\label{eq:loss_global_siamese}
\end{equation}

\begin{equation}
 \begin{split}
  \frac{\partial  J_2^g}{\partial  g(\mathbf{x}_i,\mathbf{x}_i^+,\theta_g)} = \frac{2}{N}\big[ &
(g(\mathbf{x}_i,\mathbf{x}_i^+,\theta_g) -\mu^+)\\&-\frac{1}{2}\mathds{1}((\mu^+ -\mu^-) < m)\big]\\
  \frac{\partial  J_2^g}{\partial  g(\mathbf{x}_i,\mathbf{x}_i^-,\theta_g)} = \frac{2}{N}\big[& 
(g(\mathbf{x}_i,\mathbf{x}_i^-,\theta_g) -\mu^-)\\&+\frac{1}{2}\mathds{1}((\mu^+ -\mu^-) < m)\big].\\
 \end{split}
 \label{eq:loss_global_siamese_gradient}
\end{equation}

\begin{equation}
\begin{split}
 &J_1^{tg}( \{ \mathbf{x}_i \}_{i=1}^N , \{ \mathbf{x}_i^+ \}_{i=1}^N, \{ \mathbf{x}_i^-\}_{i=1}^N ) = \\
 & \gamma \sum_j J_1^t ( \mathbf{x}_j,\mathbf{x}_j^+, \mathbf{x}_j^-)   +  J_1^g( \{ \mathbf{x}_i \}_{i=1}^N , \{ \mathbf{x}_i^+ \}_{i=1}^N, \{ \mathbf{x}_i^-\}_{i=1}^N ),\\
\end{split}
\label{eq:loss_combined}
\end{equation}
